CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,name TEXT,pw TEXT,created INTEGER);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT,kind TEXT,details TEXT,material TEXT,qty INTEGER DEFAULT 1,link TEXT,status TEXT DEFAULT 'new',created INTEGER);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,sender_id INTEGER NOT NULL,is_admin INTEGER DEFAULT 0,body TEXT,created INTEGER);
CREATE INDEX IF NOT EXISTS m_order ON messages(order_id);
